def leaves_and_gates(formula):
    """Give every leaf occurrence and gate a stable postorder token id."""
    leaves = []
    gates = []
    def visit(f):
        if isinstance(f, int):
            token = f"leaf:{len(leaves)}"
            leaves.append((token, f))
            return token
        assert isinstance(f, tuple) and len(f) == 2
        a, b = visit(f[0]), visit(f[1])
        token = f"gate:{len(gates)}"
        gates.append((token, a, b))
        return token
    root = visit(formula)
    return leaves, gates, root


def eval_formula(formula, assignment):
    if isinstance(formula, int):
        return assignment[formula]
    return 1 - eval_formula(formula[0], assignment) * eval_formula(formula[1], assignment)

